import React, { createContext, useReducer, useEffect } from 'react';
import API from '../services/api';

export const SocialMediaContext = createContext();

const initialState = {
    user: null,
    posts: [],
    notifications: [],
    isLoading: false,
    error: null
};

function reducer(state, action) {
    switch (action.type) {
        case 'FETCH_POSTS_REQUEST':
            return { ...state, isLoading: true };
        case 'FETCH_POSTS_SUCCESS':
            return { ...state, isLoading: false, posts: action.payload }; 
        case 'ADD_POST':
            return { ...state, posts: [action.payload, ...state.posts] }; 
        case 'ADD_NOTIFICATION':
            return { ...state, notifications: [action.payload, ...state.notifications] }; 
        default:
            return state;
    }
}

export function SocialMediaProvider({ children }) {
    const [state, dispatch] = useReducer(reducer, initialState);

    useEffect(() => {
        const socket = new WebSocket('ws://localhost:8080/ws'); 

        socket.onmessage = (event) => {
            const message = JSON.parse(event.data); 
            if (message.type === 'NEW_POST') {
                dispatch({ type: 'ADD_POST', payload: message.data });
            } else if (message.type === 'NOTIFICATION') {
                dispatch({ type: 'ADD_NOTIFICATION', payload: message.data }); 
            }
        };

        return () => socket.close();
    }, []);

    // Fetch posts 
    const fetchPosts = async () => {
        try {
            dispatch({ type: 'FETCH_POSTS_REQUEST' });
            const response = await API.get('/api/posts'); 
            dispatch({ type: 'FETCH_POSTS_SUCCESS', payload: response.data });
        } catch (error) {
            console.error("Error fetching posts:", error);
        }
    };

    // Create a new post
    const createPost = async (content) => {
        try {
            const response = await API.post('/api/posts', { content }); //[span_16](start_span)[span_16](end_span)
            dispatch({ type: 'ADD_POST', payload: response.data });
        } catch (error) {
            console.error('Error creating post:', error); //[span_17](start_span)[span_17](end_span)
        }
    };

    useEffect(() => {
        fetchPosts();
    }, []);

    return (
        <SocialMediaContext.Provider value={{ state, createPost, fetchPosts }}>
            {children}
        </SocialMediaContext.Provider>
    );
}
